# NOTE: All of this code was generated by AI
# The dataset came from: https://www.kaggle.com/datasets/youssefaboelwafa/hotel-booking-cancellation-prediction

library(tidymodels)  # loads parsnip, recipes, rsample, tune, yardstick, etc.
library(readr)        # for read_csv

df <- read_csv("booking.csv")  # read the CSV file into a tibble
head(df)  # print the first few rows of the tibble

df <- df |>
  select(-Booking_ID, -`date of reservation`) |>  # drop row ID and raw date string (not usable predictors as-is)
  mutate(`booking status` = factor(`booking status`))  # outcome must be a factor for classification in tidymodels

set.seed(42)  # reproducible split, matches random_state=42 used in Python

# split into train/test sets, stratifying on the outcome to preserve class proportions
split <- initial_split(df, prop = 0.8, strata = `booking status`)
train <- training(split)
test <- testing(split)

## print out proportion of people that did/did not cancel
train |> count(`booking status`) |> mutate(prop = n / sum(n))

## print out proportion of people that did/did not cancel
test |> count(`booking status`) |> mutate(prop = n / sum(n))

rec <- recipe(`booking status` ~ ., data = train) |>
  step_dummy(all_nominal_predictors())  # one-hot/dummy encode categorical predictors (trees don't need scaling)

tree_spec <- decision_tree(mode = "classification") |>  # classification tree, default hyperparameters
  set_engine("rpart")

tree_wf <- workflow() |>
  add_recipe(rec) |>  # step 1: encode categorical predictors
  add_model(tree_spec)  # step 2: fit a classification tree

tree_fit <- tree_wf |>
  fit(data = train)  # fit the workflow (recipe + tree) on the training data only

preds <- predict(tree_fit, new_data = test) |>  # run the held-out test predictors through the fitted tree
  bind_cols(test |> select(`booking status`))

preds |>
  conf_mat(truth = `booking status`, estimate = .pred_class) |>  # compare predicted vs. actual test labels
  autoplot(type = "heatmap")

accuracy_result <- preds |>
  accuracy(truth = `booking status`, estimate = .pred_class)  # proportion of correct predictions on the test set
accuracy_result  # print the tree's accuracy on the held-out test data

set.seed(1)  # reproducible folds, matches random_state=1 used in Python
folds <- vfold_cv(train, v = 10, strata = `booking status`)  # 10-fold CV, stratified like StratifiedKFold

tune_spec <- decision_tree(mode = "classification", tree_depth = tune()) |>  # tune max tree depth
  set_engine("rpart")

tune_wf <- workflow() |>
  add_recipe(rec) |>
  add_model(tune_spec)

depth_grid <- tibble(tree_depth = 1:20)  # candidate maximum tree depths to try, 1 through 20

depth_search <- tune_grid(
  tune_wf,  # same preprocessor + tree workflow as before
  resamples = folds,  # use the same stratified 10-fold CV for every candidate
  grid = depth_grid,  # the tree_depth values to search over
  metrics = metric_set(accuracy),  # select the depth that maximizes accuracy, consistent with earlier evaluation
)

best_depth <- select_best(depth_search, metric = "accuracy")  # best-performing tree_depth found
best_depth  # print the best-performing tree_depth

best_tree_wf <- finalize_workflow(tune_wf, best_depth)  # plug the best depth into the workflow

best_tree_fit <- best_tree_wf |>
  fit(data = train)  # refit on the full training data with the best tree_depth

preds_best <- predict(best_tree_fit, new_data = test) |>  # predict test labels using the depth-tuned tree
  bind_cols(test |> select(`booking status`))

preds_best |>
  conf_mat(truth = `booking status`, estimate = .pred_class) |>  # confusion matrix for the depth-tuned tree
  autoplot(type = "heatmap")

best_accuracy_result <- preds_best |>
  accuracy(truth = `booking status`, estimate = .pred_class)  # accuracy of the depth-tuned tree on the test set
best_accuracy_result  # print the depth-tuned tree's test accuracy
